// RPK Studio — MGS1 weapon/item menu picture editor (item.rpk / 5d43.r inside init.stg)
// plus the EXE menu-name (label) patcher. Self-contained standalone tool, isolated in an
// iframe overlay — same embed pattern as the Sight Editor. Host provides RPK_HOST_EXIT.
var RPK_STUDIO_HTML_B64="";
function openRpkStudio(){
  if(document.getElementById('rpkOverlay')) return;
  var ov=document.createElement('div'); ov.id='rpkOverlay';
  ov.style.cssText='position:fixed;inset:0;z-index:99999;background:#0a0e12';
  var ifr=document.createElement('iframe');
  ifr.style.cssText='border:0;width:100%;height:100%;display:block';
  ifr.srcdoc=atob(RPK_STUDIO_HTML_B64);
  ifr.onload=function(){ try{ ifr.contentWindow.RPK_HOST_EXIT=function(){ closeRpkStudio(); }; }catch(e){} };
  ov.appendChild(ifr); document.body.appendChild(ov);
}
function closeRpkStudio(){ var ov=document.getElementById('rpkOverlay'); if(ov) ov.remove(); }
